/** A bounded proof of an existing WASM endpoint. Inputs must remain exclusively
 * owned by this render; returned bytes are not changed or transferred. */
export function filteredMixEndpoint(
  original:Uint8ClampedArray,filtered:Uint8ClampedArray,mask:Uint8ClampedArray,
  density=1,inverted=false,
):Uint8ClampedArray|undefined {
  // Decline invalid inputs so the existing worker keeps its validation/errors.
  if(!(original instanceof Uint8ClampedArray)||!(filtered instanceof Uint8ClampedArray)||!(mask instanceof Uint8ClampedArray)||
      ![original,filtered,mask].every(value=>value.buffer instanceof ArrayBuffer)||
      !original.length||original.length%4||original.length!==filtered.length||original.length!==mask.length||
      original.length>0x7ffffffc||!Number.isFinite(density)||density<0||density>1||typeof inverted!=='boolean')return undefined;
  if(density===0)return filtered;
  const first=mask[3];
  if(first!==0&&first!==255)return undefined;
  const coverage=inverted?255-first:first;
  if(coverage===0&&density!==1)return undefined;
  // Larger regions keep the worker path; this is a probe-work budget, never an
  // image/document limit. It prevents an endpoint search from becoming a long task.
  if(mask.length>262144*4)return undefined;
  for(let i=7;i<mask.length;i+=4)if(mask[i]!==first)return undefined;
  return coverage===0?original:filtered;
}

