  // full-flow prefix. Publish these only with its privately completed canvas.
  private opacityBounds=new Map<string,number>();
  private nonOpaqueBounds=new Map<string,TextureReadbackRegion>();
  private points:readonly StrokePoint[]=[];
  private identities=new WeakMap<ImageBitmap,number>();
  private sequence=0;
  private generation=0;
  private disposed=false;
